//! Embeds `assets/mbrowser.ico` into the exe as icon resource #1, so Explorer,
//! shortcuts, the taskbar and the window itself all show the app icon.
//!
//! The `.res` file is written directly (it is a simple binary format), so the
//! build needs neither rc.exe / the Windows SDK nor extra crates. The icon itself
//! is generated by `tools/make_icon.py`.

use std::{env, fs, path::PathBuf};

const ICON: &str = "assets/mbrowser.ico";
/// Resource id of the icon group; `app::app_icon` loads it by this id.
const ICON_ID: u16 = 1;

const RT_ICON: u16 = 3;
const RT_GROUP_ICON: u16 = 14;

fn main() {
    println!("cargo:rerun-if-changed={ICON}");
    if env::var("CARGO_CFG_TARGET_OS").as_deref() != Ok("windows") {
        return;
    }
    if env::var("CARGO_CFG_TARGET_ENV").as_deref() != Ok("msvc") {
        println!("cargo:warning=app icon is embedded only with the MSVC toolchain");
        return;
    }
    let ico = fs::read(ICON).unwrap_or_else(|e| panic!("{ICON}: {e}"));
    let res = PathBuf::from(env::var("OUT_DIR").unwrap()).join("mbrowser.res");
    fs::write(&res, ico_to_res(&ico)).unwrap();
    // link.exe takes compiled resources as a plain input file.
    println!("cargo:rustc-link-arg-bins={}", res.display());
}

/// .ico → .res: every image becomes an RT_ICON, plus one RT_GROUP_ICON listing them.
fn ico_to_res(ico: &[u8]) -> Vec<u8> {
    let u16_at = |i: usize| u16::from_le_bytes([ico[i], ico[i + 1]]);
    let u32_at = |i: usize| u32::from_le_bytes(ico[i..i + 4].try_into().unwrap());
    assert!(ico.len() >= 6 && u16_at(0) == 0 && u16_at(2) == 1, "{ICON} is not an .ico file");
    let count = u16_at(4);

    let mut res = Vec::new();
    resource(&mut res, 0, 0, 0, &[]); // the empty entry every .res file starts with
    let mut group = Vec::new();
    group.extend_from_slice(&[0, 0, 1, 0]);
    group.extend_from_slice(&count.to_le_bytes());
    for n in 0..count {
        let e = 6 + 16 * n as usize;
        let (size, offset) = (u32_at(e + 8) as usize, u32_at(e + 12) as usize);
        let id = n + 1;
        resource(&mut res, RT_ICON, id, 0x1010, &ico[offset..offset + size]);
        group.extend_from_slice(&ico[e..e + 12]); // size, colors, planes, bpp, bytes
        group.extend_from_slice(&id.to_le_bytes());
    }
    resource(&mut res, RT_GROUP_ICON, ICON_ID, 0x1030, &group);
    res
}

/// Appends one resource: a 32-byte header (ordinal type and name) and DWORD-aligned data.
fn resource(out: &mut Vec<u8>, kind: u16, id: u16, flags: u16, data: &[u8]) {
    out.extend_from_slice(&(data.len() as u32).to_le_bytes());
    out.extend_from_slice(&32u32.to_le_bytes());
    for v in [0xFFFF, kind, 0xFFFF, id] {
        out.extend_from_slice(&u16::to_le_bytes(v));
    }
    out.extend_from_slice(&0u32.to_le_bytes()); // data version
    out.extend_from_slice(&flags.to_le_bytes());
    out.extend_from_slice(&0u16.to_le_bytes()); // language: neutral
    out.extend_from_slice(&[0; 8]); // version, characteristics
    out.extend_from_slice(data);
    out.resize(out.len().next_multiple_of(4), 0);
}
